CREATE OR REPLACE FUNCTION public.fn_ca_autoledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  spec text; col text; acct text;
  o jsonb; nn jsonb;
  d numeric; oldv numeric; newv numeric;
  cat text; cp text; cpid uuid; cplbl text;
  v_club uuid; v_union uuid; v_entity uuid; v_guc_club uuid;
  actor uuid;
  v_st text; v_msg text;
BEGIN
  IF current_setting('app.ledger_autoskip_' || TG_TABLE_NAME, true) = '1' THEN
    RETURN NEW;
  END IF;

  o  := CASE WHEN TG_OP = 'INSERT' THEN '{}'::jsonb ELSE to_jsonb(OLD) END;
  nn := to_jsonb(NEW);

  cat := COALESCE(NULLIF(current_setting('app.ledger_category', true), ''), 'adjustment');
  cp  := COALESCE(NULLIF(current_setting('app.ledger_counterparty', true), ''), 'settlement_suspense');
  BEGIN
    cpid := NULLIF(current_setting('app.ledger_counterparty_entity', true), '')::uuid;
  EXCEPTION WHEN OTHERS THEN cpid := NULL;
  END;
  /* THE COUNTERPARTY NAMES ITS COLUMN (2026-10-04). A union wallet holds six
     balances and a promo bank lives on three kinds of owner, so the side this
     trigger writes for a declared union_wallet or promo_wallet counterparty
     carries the column the caller declared on app.ledger_counterparty_label.
     A label that cannot belong to the declared counterparty is not written:
     a stale declaration never names the wrong account. */
  cplbl := NULLIF(current_setting('app.ledger_counterparty_label', true), '');
  cplbl := CASE
    WHEN cp = 'union_wallet' AND cplbl LIKE 'union_wallets.%' THEN cplbl
    WHEN cp = 'promo_wallet' AND cplbl IN ('clubs.promo_balance', 'agents.promo_wallet_balance',
                                           'union_wallets.promo_wallet') THEN cplbl
    ELSE NULL END;
  actor := COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid);

  /* THE JOURNAL LEG NAMES THE CLUB THE MONEY LANDED IN (2026-09-20).
     union_wallets and unions are the only autoledgered tables with no
     club_id column - `nn ? 'club_id'` is key EXISTENCE, so a table
     that has the column takes the arm above even when it is NULL. Before
     today every leg journalled from those two was written club-less, and
     fn_chip_drift_since_baseline filters movements on club_id IS NOT
     NULL while counting the balance they explain, so correctly paid
     union-hosted prizes were reported as member drift.
     A payer that knows the club declares it on
     app.ledger_autoledger_club_id, transaction-scoped, and clears it
     beside the autoskips. It is deliberately NOT app.ledger_club_id:
     that name is taken and decides which club a WALLET credit is paid
     into (atomic_credit_wallet_and_log, atomic_deduct_wallet_and_log,
     log_wallet_transaction), so borrowing it would let a rakeback
     close's club leak onto a union leg and would move real money when
     cleared. Read through an exception guard exactly as cpid is above:
     a malformed value must never abort a chip movement. */
  BEGIN
    v_guc_club := NULLIF(current_setting('app.ledger_autoledger_club_id', true), '')::uuid;
  EXCEPTION WHEN OTHERS THEN v_guc_club := NULL;
  END;
  v_club := CASE
    WHEN TG_TABLE_NAME = 'clubs' THEN (nn->>'id')::uuid
    WHEN nn ? 'club_id' THEN NULLIF(nn->>'club_id','')::uuid
    ELSE v_guc_club END;
  v_union := CASE
    WHEN TG_TABLE_NAME = 'unions' THEN (nn->>'id')::uuid
    WHEN nn ? 'union_id' THEN NULLIF(nn->>'union_id','')::uuid
    ELSE NULL END;
  v_entity := CASE
    WHEN TG_TABLE_NAME = 'agents' THEN NULLIF(nn->>'user_id','')::uuid
    WHEN TG_TABLE_NAME = 'club_members' THEN NULLIF(nn->>'user_id','')::uuid
    ELSE COALESCE(NULLIF(nn->>'id','')::uuid, v_club, v_union) END;

  FOR i IN 0 .. TG_NARGS - 1 LOOP
    spec := TG_ARGV[i];
    col  := split_part(spec, '=', 1);
    acct := split_part(spec, '=', 2);
    oldv := COALESCE(NULLIF(o->>col,'')::numeric, 0);
    newv := COALESCE(NULLIF(nn->>col,'')::numeric, 0);
    d := round(newv - oldv, 2);
    CONTINUE WHEN d = 0;
    /* THE AUTOLEDGER NEVER JOURNALS AN ACCOUNT TO ITSELF (2026-10-15). A leg
       whose counterparty is this very account, unlabelled, is from and to the
       same account (2026-10-06 15:42 KF player to three club treasuries;
       2026-09-17 16:39/16:41 treasury to promo). It nets to zero in every
       tally, so it is not written. A bbj_pool, a union_wallet and a promo bank
       off a club hold more than one column under one key, and their bare
       self-legs are the only record of which column moved: kept. */
    CONTINUE WHEN cp = acct AND cpid IS NOT DISTINCT FROM v_entity AND cplbl IS NULL
              AND acct NOT IN ('bbj_pool', 'union_wallet')
              AND (acct <> 'promo_wallet' OR TG_TABLE_NAME = 'clubs');

    BEGIN
      INSERT INTO public.chip_ledger
        (performed_by, from_type, from_entity_id, from_label,
         to_type, to_entity_id, to_label,
         amount, category, club_id, union_id, description,
         pre_from_balance, post_from_balance, pre_to_balance, post_to_balance)
      VALUES (actor,
        CASE WHEN d > 0 THEN cp   ELSE acct END,
        CASE WHEN d > 0 THEN cpid ELSE v_entity END,
        CASE WHEN d > 0 THEN cplbl ELSE TG_TABLE_NAME || '.' || col END,
        CASE WHEN d > 0 THEN acct ELSE cp END,
        CASE WHEN d > 0 THEN v_entity ELSE cpid END,
        CASE WHEN d > 0 THEN TG_TABLE_NAME || '.' || col ELSE cplbl END,
        abs(d), cat, v_club, v_union,
        'auto-ledgered ' || TG_TABLE_NAME || '.' || col || ' delta ' || d::text,
        CASE WHEN d < 0 THEN oldv END, CASE WHEN d < 0 THEN newv END,
        CASE WHEN d > 0 THEN oldv END, CASE WHEN d > 0 THEN newv END);
    EXCEPTION WHEN OTHERS THEN
      -- A journal failure must abort the enclosing chip movement.
      -- Preserve SQLSTATE so the existing caller can retry the whole operation.
      RAISE;
    END;
  END LOOP;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_issue_scope_weekly_accounting(p_scope_kind text, p_scope_id uuid, p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_variable
DECLARE scope record;club uuid;period public.settlement_periods%ROWTYPE;report jsonb;invoice uuid;issued int:=0;period_count int;clubs uuid[];delivery jsonb;expected_users int;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501';END IF;
 IF p_from IS NULL OR p_to IS NULL OR NOT isfinite(p_from) OR NOT isfinite(p_to)
  OR p_from IS DISTINCT FROM public.fn_union_week_start(p_from) OR p_to IS DISTINCT FROM public.fn_union_week_start(p_from+interval '8 days') OR p_to>now()
 THEN RAISE EXCEPTION 'weekly_statement_requires_closed_week' USING ERRCODE='22023';END IF;
 IF current_setting('app.accounting_validated_scope',true) IS DISTINCT FROM p_scope_kind||':'||p_scope_id::text||':'||p_from::text||':'||p_to::text
 THEN RAISE EXCEPTION 'weekly_statement_requires_validated_scope' USING ERRCODE='23514';END IF;
 SELECT * INTO scope FROM public.fn_resolve_accounting_routing_scope(p_scope_kind,p_scope_id,p_from,p_to);
 SELECT COALESCE(array_agg(x.club_id ORDER BY x.club_id),ARRAY[]::uuid[]) INTO clubs FROM (
  SELECT c.club_id FROM public.fn_accounting_week_clubs(scope.union_id,scope.standalone_club_id,p_from,p_to)c
  UNION SELECT s.club_id FROM public.accounting_payable_earning_sources s WHERE s.earned_at>=p_from AND s.earned_at<p_to
   AND (s.coordinator_union_id=scope.union_id OR (scope.standalone_club_id=s.club_id AND s.coordinator_union_id IS NULL)) AND s.club_id IS NULL
  UNION SELECT sp.club_id FROM public.settlement_periods sp WHERE sp.start_at=p_from AND sp.end_at=p_to AND sp.club_id IS NOT NULL
   AND (sp.union_id=scope.union_id OR (sp.club_id=scope.standalone_club_id AND sp.union_id IS NULL))
 )x WHERE x.club_id IS DISTINCT FROM scope.union_id;
 FOREACH club IN ARRAY clubs LOOP
  SELECT count(*) INTO period_count FROM public.settlement_periods sp WHERE sp.club_id=club AND sp.union_id IS NOT DISTINCT FROM scope.union_id AND sp.start_at=p_from AND sp.end_at=p_to;
  IF period_count<>1 THEN RAISE EXCEPTION 'weekly_statement_period_missing_or_duplicated' USING ERRCODE='23514',DETAIL=jsonb_build_object('club_id',club,'period_count',period_count)::text;END IF;
  SELECT * INTO period FROM public.settlement_periods sp WHERE sp.club_id=club AND sp.union_id IS NOT DISTINCT FROM scope.union_id AND sp.start_at=p_from AND sp.end_at=p_to FOR UPDATE;
  PERFORM pg_advisory_xact_lock(hashtextextended('club_weekly_invoice:'||period.id::text,0));
  SELECT i.id INTO invoice FROM public.settlement_invoices i WHERE i.period_id=period.id AND i.club_id=club AND i.invoice_type='club_weekly_accounting';
  IF invoice IS NULL THEN
   report:=public.fn_club_weekly_accounting_summary(period.id);
   IF report->>'ready_to_issue' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'club_weekly_statement_requires_reconciliation' USING ERRCODE='23514',DETAIL=report::text;END IF;
   report:=report||jsonb_build_object('status','complete');
   INSERT INTO public.settlement_invoices(club_id,period_id,invoice_type,from_entity_type,from_entity_id,to_entity_type,to_entity_id,gross_amount,net_amount,deductions,breakdown,status,notes)
   VALUES(club,period.id,'club_weekly_accounting','club',club::text,'club',club::text,(report->>'total_rake_funding')::numeric,(report->>'retained_by_club')::numeric,
    (report->>'total_paid_by_club')::numeric,report,'generated','Consolidated Weekly Club Accounting. The Net Movement Is Not An Additional Bill Or Transfer.') RETURNING id INTO invoice;
   issued:=issued+1;
  END IF;
  delivery:=public.fn_deliver_accounting_invoice(invoice);
  SELECT count(*) INTO expected_users FROM public.fn_accounting_party_users('club',club);
  IF delivery->>'success' IS DISTINCT FROM 'true' /* HISTORY-ONLY INVOICE (20261016143729) */ OR expected_users=0 OR (SELECT si.message_sent IS NOT TRUE FROM public.settlement_invoices si WHERE si.id=invoice)
   OR ((SELECT si.invoice_type FROM public.settlement_invoices si WHERE si.id=invoice) IS NOT DISTINCT FROM 'cashier_cashout' AND EXISTS(
   SELECT 1 FROM public.fn_accounting_party_users('club',club)u WHERE NOT EXISTS(SELECT 1 FROM public.accounting_invoice_deliveries d
    JOIN public.social_messages m ON m.id=d.message_id JOIN public.notifications n ON n.id=d.notification_id
    WHERE d.invoice_id=invoice AND d.recipient_id=u.user_id AND m.media_metadata->>'invoice_id'=invoice::text AND n.user_id=u.user_id
     AND m.message_type='invoice' AND n.metadata->>'invoice_id'=invoice::text)))
  THEN RAISE EXCEPTION 'club_weekly_statement_delivery_incomplete' USING ERRCODE='23514';END IF;
 END LOOP;
 RETURN jsonb_build_object('success',true,'scope_kind',p_scope_kind,'scope_id',p_scope_id,'period_start',p_from,'period_end',p_to,'clubs',cardinality(clubs),'issued',issued);
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_chip_ledger_enrich()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prev text;
BEGIN
  NEW.amount := round(NEW.amount, 2);
  NEW.created_at := COALESCE(NEW.created_at, now());

  NEW.epoch_id      := COALESCE(NEW.epoch_id, public.fn_ca_current_epoch());
  NEW.actor_service := COALESCE(NEW.actor_service,
                                current_setting('application_name', true));
  NEW.db_role       := COALESCE(NEW.db_role, current_user);
  NEW.correlation_id := COALESCE(NEW.correlation_id,
      NULLIF(current_setting('app.ledger_correlation', true), '')::uuid);
  NEW.settlement_id  := COALESCE(NEW.settlement_id,
      NULLIF(current_setting('app.ledger_settlement', true), ''));
  IF NEW.idempotency_key IS NULL THEN
    NEW.idempotency_key := NULLIF(current_setting('app.ledger_idempotency_key', true), '');
    IF NEW.idempotency_key IS NOT NULL THEN
      -- consume-once: the next row in this transaction must not inherit it
      PERFORM set_config('app.ledger_idempotency_key', '', true);
    END IF;
  END IF;

  /* PHASE 6.4 (2026-09-05): EVERY LEG NAMES ITS HAND OR ITS EVENT. The doors
     that know the hand say so on app.ledger_hand_id (the rake door and the
     BBJ drop, since today) or on a 'bbj:<hand>' settlement; the rake
     settlement is not read for it because it carries a random key when the
     hand is unknown, and a guessed hand is worse than none; a spin's reserve legs
     carry the spin on their prize_liability side. Read them here, once, so
     the hand and the event are columns a per-hand audit can index on rather
     than strings it has to parse. 231,211 legs a day; 29,617 named a hand
     and 50,359 an event before this. */
  IF NEW.hand_id IS NULL THEN
    NEW.hand_id := NULLIF(current_setting('app.ledger_hand_id', true), '')::uuid;
    IF NEW.hand_id IS NULL AND NEW.settlement_id ~ '^bbj:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      NEW.hand_id := split_part(NEW.settlement_id, ':', 2)::uuid;
    END IF;
  END IF;
  IF NEW.tournament_id IS NULL THEN
    NEW.tournament_id := NULLIF(current_setting('app.ledger_tournament_id', true), '')::uuid;
    /* PHASE 6 GATE (2026-09-05): a prize_liability side IS the event, on every
       category, not only the two spin ones. This is what the 6.4 measurement
       missed: 777 tournament rake settlements in three hours (the fee leaving
       an event to a union rake wallet or a club treasury) and every tournament
       add-on named nothing. Read against the rows first: all 777 from_entity_id
       values are real tournaments. The FROM side wins when both sides are
       prize_liability (a satellite seat's pool transfer, which already stamps
       the satellite itself). */
    IF NEW.tournament_id IS NULL THEN
      IF NEW.from_type = 'prize_liability' THEN NEW.tournament_id := NEW.from_entity_id;
      ELSIF NEW.to_type = 'prize_liability' THEN NEW.tournament_id := NEW.to_entity_id;
      END IF;
    END IF;
  END IF;
  /* PHASE 6 GATE: and a table_stack side IS the table. Every cash buy-in,
     add-on and cash-out carries the table on its felt side (231, 53 and 222
     of each measured in the same window, every one a real table row) and
     none of them carried table_id. A cash buy-in is not a hand; the table is
     the name it has. */
  IF NEW.table_id IS NULL THEN
    IF NEW.to_type = 'table_stack' THEN NEW.table_id := NEW.to_entity_id;
    ELSIF NEW.from_type = 'table_stack' THEN NEW.table_id := NEW.from_entity_id;
    END IF;
  END IF;

  -- Tamper evidence: monotone sequence + per-row content checksum. NOT chained
  -- through the previous row's hash at insert time - that would put a global
  -- serialization point (and deadlock surface) inside every money transaction,
  -- which the availability policy forbids. prev_hash is best-effort forensics.
  NEW.chain_seq := nextval('public.chip_ledger_chain_seq');
  SELECT row_hash INTO v_prev
    FROM public.chip_ledger
   WHERE chain_seq = NEW.chain_seq - 1;
  NEW.prev_hash := v_prev;
  NEW.row_hash := encode(extensions.digest(
      'v1'
      || '|' || NEW.chain_seq::text
      || '|' || COALESCE(NEW.epoch_id::text,'')
      || '|' || NEW.amount::text
      || '|' || NEW.from_type || ':' || COALESCE(NEW.from_entity_id::text,'')
      || '|' || NEW.to_type   || ':' || COALESCE(NEW.to_entity_id::text,'')
      || '|' || NEW.category
      || '|' || COALESCE(NEW.idempotency_key,'')
      || '|' || COALESCE(NEW.correlation_id::text,'')
      || '|' || NEW.created_at::text,
      'sha256'), 'hex');
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_declare_ledger(p_category text, p_counterparty text, p_counterparty_entity uuid DEFAULT NULL::uuid, p_settlement_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_autoskip_tables text[] DEFAULT NULL::text[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_t text;
BEGIN
  -- validate against the LIVE vocabulary so this can never lag a CHECK change
  IF p_category IS NULL OR NOT EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conrelid = 'public.chip_ledger'::regclass
       AND conname = 'chip_ledger_category_check'
       AND pg_get_constraintdef(oid) LIKE '%''' || p_category || '''%') THEN
    RAISE EXCEPTION 'fn_ca_declare_ledger: category % is not in the ledger vocabulary - add it to chip_ledger_category_check FIRST, then declare it', p_category;
  END IF;
  IF p_counterparty IS NULL OR NOT EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conrelid = 'public.chip_ledger'::regclass
       AND conname = 'chip_ledger_from_type_check'
       AND pg_get_constraintdef(oid) LIKE '%''' || p_counterparty || '''%') THEN
    RAISE EXCEPTION 'fn_ca_declare_ledger: counterparty % is not in the ledger vocabulary - add it to the from/to type CHECKs FIRST, then declare it', p_counterparty;
  END IF;

  PERFORM set_config('app.ledger_category', p_category, true);
  PERFORM set_config('app.ledger_counterparty', p_counterparty, true);
  PERFORM set_config('app.ledger_counterparty_entity',
                     COALESCE(p_counterparty_entity::text, ''), true);
  /* A COUNTERPARTY NAMES ITS COLUMN, AND A NEW DECLARATION FORGETS THE LAST
     ONE'S (2026-10-04). A union wallet holds six balances; the caller whose
     counterparty is one of them names it on app.ledger_counterparty_label
     after this call, and fn_ca_autoledger writes it on that side. */
  PERFORM set_config('app.ledger_counterparty_label', '', true);
  IF p_settlement_id IS NOT NULL THEN
    PERFORM set_config('app.ledger_settlement', p_settlement_id::text, true);
  END IF;
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM set_config('app.ledger_idempotency_key', p_idempotency_key, true);
  END IF;
  IF p_autoskip_tables IS NOT NULL THEN
    FOREACH v_t IN ARRAY p_autoskip_tables LOOP
      IF v_t !~ '^[a-z_]+$' THEN
        RAISE EXCEPTION 'fn_ca_declare_ledger: bad autoskip table name %', v_t;
      END IF;
      PERFORM set_config('app.ledger_autoskip_' || v_t, '1', true);
    END LOOP;
  END IF;
END $function$

CREATE OR REPLACE FUNCTION public.fn_bank_standalone_week_rake(p_club_id uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_name text;
  v_cash numeric;
  v_fees numeric;
  v_total numeric;
  v_key text;
  v_res jsonb;
  v_cat text := COALESCE(current_setting('app.ledger_category', true), '');
  v_cp text := COALESCE(current_setting('app.ledger_counterparty', true), '');
  v_cpe text := COALESCE(current_setting('app.ledger_counterparty_entity', true), '');
  v_idem text := COALESCE(current_setting('app.ledger_idempotency_key', true), '');
BEGIN
  IF NOT public.fn_caller_is_engine() THEN
    RAISE EXCEPTION 'not_authorised' USING ERRCODE = '42501';
  END IF;
  IF p_club_id IS NULL OR p_period_start IS NULL OR p_period_end IS NULL
     OR p_period_start <> public.fn_union_week_start(p_period_start)
     OR p_period_end <> public.fn_union_week_start(p_period_start + interval '8 days')
     OR p_period_end > public.fn_union_week_start(clock_timestamp()) THEN
    RAISE EXCEPTION 'standalone_rake_bank_invalid_week' USING ERRCODE = '22023';
  END IF;
  SELECT c.name INTO v_name FROM public.clubs c
   WHERE c.id = p_club_id AND c.is_union IS NOT TRUE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'standalone_rake_bank_unknown_club' USING ERRCODE = '22023';
  END IF;

  -- Cash: the standalone bank receipt every retired cash rake leg carries.
  SELECT COALESCE(sum(b.amount), 0) INTO v_cash
    FROM public.accounting_cash_bank_receipts b
   WHERE b.union_id IS NULL AND b.club_id = p_club_id
     AND b.club_ledger_id IS NOT NULL
     AND b.banked_at >= p_period_start AND b.banked_at < p_period_end;
  -- Tournament fees: the settlement row of every standalone fee retirement.
  SELECT COALESCE(sum(s.amount), 0) INTO v_fees
    FROM public.tournament_rake_settlements s
   WHERE s.destination = 'chip_retirement:' || p_club_id::text
     AND s.settled_at >= p_period_start AND s.settled_at < p_period_end;
  v_total := v_cash + v_fees;
  IF v_total <= 0 THEN
    RETURN jsonb_build_object('ok', true, 'amount', 0, 'club_id', p_club_id,
      'period_start', p_period_start, 'period_end', p_period_end);
  END IF;

  v_key := 'standalone-rake-bank:' || p_club_id::text || ':'
    || to_char(p_period_start AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') || '..'
    || to_char(p_period_end AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');
  v_res := public.fn_ca_fund_club(
    p_club_id, v_total,
    'Weekly bank of the standalone rake ' || COALESCE(v_name, p_club_id::text)
      || ' retired in the week ' || to_char(p_period_start AT TIME ZONE 'UTC', 'YYYY-MM-DD')
      || '..' || to_char(p_period_end AT TIME ZONE 'UTC', 'YYYY-MM-DD')
      || ' (cash ' || v_cash::text || ', tournament fees ' || v_fees::text
      || '); standalone rake belongs to the club treasury (CLUB-MONEY-LEDGERS-CANONICAL)',
    v_key);
  PERFORM set_config('app.ledger_category', v_cat, true);
  PERFORM set_config('app.ledger_counterparty', v_cp, true);
  PERFORM set_config('app.ledger_counterparty_entity', v_cpe, true);
  PERFORM set_config('app.ledger_idempotency_key', v_idem, true);
  IF v_res->>'ok' IS DISTINCT FROM 'true' THEN
    RAISE EXCEPTION 'standalone_rake_bank_refused' USING DETAIL = v_res::text;
  END IF;
  RETURN v_res || jsonb_build_object('cash_rake', v_cash, 'tournament_fees', v_fees,
    'period_start', p_period_start, 'period_end', p_period_end);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_fund_club(p_club_id uuid, p_amount numeric, p_reason text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_club record; v_key text; v_before numeric; v_after numeric;
  v_leg uuid; v_supply numeric; v_reason text := btrim(COALESCE(p_reason, ''));
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 OR p_amount <> round(p_amount, 2) THEN
    RAISE EXCEPTION 'fund_club refused: amount must be positive to two decimals';
  END IF;
  IF length(v_reason) < 10 THEN
    RAISE EXCEPTION 'fund_club refused: a reason of at least 10 characters is required';
  END IF;
  SELECT * INTO v_club FROM public.clubs WHERE id = p_club_id FOR NO KEY UPDATE;
  IF v_club.id IS NULL THEN
    RAISE EXCEPTION 'fund_club refused: unknown club %', p_club_id;
  END IF;
  v_key := COALESCE(p_idempotency_key,
                    'club-funding:' || p_club_id::text || ':' ||
                    extract(epoch from clock_timestamp())::bigint::text);
  -- Replay safety: an identical key that already journaled is a no-op.
  IF EXISTS (SELECT 1 FROM public.chip_ledger WHERE idempotency_key = v_key) THEN
    RETURN jsonb_build_object('ok', true, 'replayed', true, 'idempotency_key', v_key);
  END IF;
  v_before := COALESCE(v_club.chip_treasury, 0);

  PERFORM public.fn_ca_declare_ledger('mint', 'system_mint', NULL, NULL, v_key);
  UPDATE public.clubs
     SET chip_treasury = COALESCE(chip_treasury,0) + p_amount
   WHERE id = p_club_id
   RETURNING chip_treasury INTO v_after;
  SELECT id INTO v_leg FROM public.chip_ledger WHERE idempotency_key = v_key;
  -- The declaration is this mint's alone: a later write in the same
  -- transaction must never be journalled as house issuance.
  PERFORM set_config('app.ledger_category', '', true);
  PERFORM set_config('app.ledger_counterparty', '', true);
  PERFORM set_config('app.ledger_counterparty_entity', '', true);
  PERFORM set_config('app.ledger_idempotency_key', '', true);
  IF v_leg IS NULL THEN
    RAISE EXCEPTION 'fund_club: the treasury moved but no journal leg carries key % - refusing to mint what the journal does not carry', v_key;
  END IF;

  -- The register row is the door's, with the door's reason (2026-10-02): the
  -- commit-time check refuses a system_mint leg without one.
  SELECT COALESCE(SUM(CASE WHEN action = 'mint' THEN amount ELSE -amount END), 0) + p_amount
    INTO v_supply FROM public.ca_mint_ledger WHERE asset = 'chips';
  INSERT INTO public.ca_mint_ledger
    (op_id, action, asset, holder_type, holder_id, holder_label, amount,
     balance_before, balance_after, supply_after, reason,
     performed_by, performed_by_label, chip_ledger_id)
  VALUES
    (v_key, 'mint', 'chips',
     CASE WHEN COALESCE(v_club.is_union, false) THEN 'union' ELSE 'club' END,
     p_club_id, v_club.name, p_amount,
     v_before, v_after, v_supply, left(v_reason, 2000),
     auth.uid(), 'fn_ca_fund_club', v_leg);

  RETURN jsonb_build_object('ok', true, 'replayed', false, 'club_id', p_club_id,
                            'amount', p_amount, 'treasury_after', v_after,
                            'idempotency_key', v_key, 'reason', v_reason,
                            'ledger_id', v_leg);
END $function$
